-- Engelsk katalogindhold og events fra det gamle Lovable-site.
--
-- De tre kataloger fandtes allerede på dansk; her kommer de engelske rækker
-- til, sammen med en ny events-tabel i begge sprog. Rækkerne er idempotente,
-- så migrationen kan køres igen uden dubletter.

-- Ressourcerne kan være på et andet sprog end den side, de vises på: en dansk
-- podcast optræder også i det engelske katalog. Kolonnen gør det muligt at
-- mærke det i stedet for at skjule indholdet.
alter table public.resources
  add column if not exists content_language text not null default 'da';

do $$ begin
  alter table public.resources
    add constraint resources_content_language_check check (content_language in ('da', 'en'));
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.catalog_event_location as enum ('fysisk', 'online', 'hybrid');
exception when duplicate_object then null; end $$;

create table if not exists public.events (
  id uuid primary key default gen_random_uuid(),
  slug text not null,
  title text not null,
  description text not null default '',
  event_date timestamptz not null,
  time_start text,
  time_end text,
  location_type public.catalog_event_location not null default 'fysisk',
  location_name text,
  registration_url text,
  organizer text,
  price text,
  published boolean not null default false,
  locale public.catalog_locale not null default 'da',
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (slug, locale)
);

create index if not exists events_published_idx on public.events (locale, published, event_date);

drop trigger if exists events_touch_updated_at on public.events;
create trigger events_touch_updated_at before update on public.events
  for each row execute function public.touch_updated_at();

alter table public.events enable row level security;

drop policy if exists events_public_read on public.events;
create policy events_public_read on public.events
  for select to anon, authenticated using (published);

drop policy if exists events_manager_read on public.events;
create policy events_manager_read on public.events
  for select to authenticated using (private.is_content_manager());

drop policy if exists events_manager_write on public.events;
create policy events_manager_write on public.events
  for all to authenticated
  using (private.is_content_manager())
  with check (private.is_content_manager());

grant select on public.events to anon, authenticated;
grant insert, update, delete on public.events to authenticated;

-- Migreret indhold. Danske rækker, der allerede findes, springes over.
on conflict (slug, locale) do nothing;

on conflict (slug, locale) do nothing;

on conflict (slug, locale) do nothing;

on conflict (slug, locale) do nothing;
